export function screenById(id: string): ScreenDef | undefined {
  return SCREENS.find((s) => s.id === id);
}

export function screensByModule(moduleId: string): ScreenDef[] {
  return SCREENS.filter((s) => s.module === moduleId);
}

export function screensForRoute(route: string): ScreenDef[] {
  return SCREENS.filter((s) => s.route === route);
}
